167			t.Fatalf("rejected grant persisted valid part: %d authorizations", len(auths))
168		}
169		if got := len(mustAudit(t, f.s, f.pid)); got != auditBefore {
170			t.Fatalf("rejected grant added audit: before=%d after=%d", auditBefore, got)
171		}
172	}
