246		totalBefore := totalAuthorizations(f.s)
247	
248		// 1) 直接改写返回结果上撤回时间“所指的时刻”（不只是给字段换一个指针），
249		// 用以验证撤回时间与库内对象是深拷贝隔离的。
250		rowsA, err := f.s.ListAuthorizations(doc, pid, "")
251		if err != nil {
252			t.Fatalf("list A: %v", err)
253		}
254		fakeTime := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
255		*listedAuthPtr(t, rowsA, f.mixed.ID).RevokedAt = fakeTime
256	
257		// 2) 在另一份本地结果上把撤回标记清空，伪装成从未撤回。
258		rowsB, err := f.s.ListAuthorizations(doc, pid, rcv.ID)
259		if err != nil {
260			t.Fatalf("list B: %v", err)
261		}
262		listedAuthPtr(t, rowsB, f.mixed.ID).RevokedAt = nil
263	
264		// 本地两份各自呈现篡改后的样子，互不影响。
265		if got := findListedAuth(t, rowsA, f.mixed.ID).RevokedAt; got == nil || !got.Equal(fakeTime) {
266			t.Fatalf("local copy A revoke time = %v, want local fake %v", got, fakeTime)
267		}
268		if got := findListedAuth(t, rowsB, f.mixed.ID).RevokedAt; got != nil {
269			t.Fatalf("local copy B revoke marker = %v, want cleared locally", got)
270		}
271	
272		// 正式授权仍保留首次撤回时间。
273		stored, err := f.s.GetAuthorization(doc, pid, f.mixed.ID)
274		if err != nil {
275			t.Fatalf("get mixed: %v", err)
276		}
277		if stored.RevokedAt == nil || !stored.RevokedAt.Equal(firstRevokedAt) {
278			t.Fatalf("stored revoke time = %v, want first revoke time %v",
279				stored.RevokedAt, firstRevokedAt)
280		}
281	
282		// 时钟前进后重复撤回仍是幂等确认：不能把首次撤回时间改写成本次时刻。
283		f.clk.t = f.clk.t.Add(2 * time.Hour)
284		if err := f.s.Revoke(doc, pid, f.mixed.ID); err != nil {
285			t.Fatalf("idempotent re-revoke: %v", err)
286		}
287		stored, err = f.s.GetAuthorization(doc, pid, f.mixed.ID)
288		if err != nil {
289			t.Fatalf("re-get mixed: %v", err)
290		}
291		if stored.RevokedAt == nil || !stored.RevokedAt.Equal(firstRevokedAt) {
292			t.Fatalf("first revoke time overwritten: got %v, want %v",
293				stored.RevokedAt, firstRevokedAt)
294		}
295	
296		// 手中清单看起来未撤回，接收方仍读不到内容：医嘱唯一授权已撤回，拒绝且无内容。
297		denied, err := f.s.Read(rcv, pid, f.e, Order)
298		assertDeniedWithoutContent(t, denied, err, "orders with locally un-revoked list")
299		// 诊断类别不受本地清空撤回影响：仍只有 dx1，dx2 不随“复活”的混合授权回来。
300		res, err := f.s.Read(rcv, pid, f.e, Diagnosis)
301		if err != nil {
302			t.Fatalf("dx1 read: %v", err)
303		}
304		if ids := readRecordIDs(res); len(res.Records) != 1 || !ids[f.dx1] || ids[f.dx2] {
305			t.Fatalf("diagnosis read after local un-revoke = %v, want only dx1", ids)
306		}
307	
308		// 重新查询仍只反映正式保存的撤回状态与首次撤回时间。
309		refreshed, err := f.s.ListAuthorizations(doc, pid, "")
310		if err != nil {
311			t.Fatalf("relist: %v", err)
312		}
313		relisted := findListedAuth(t, refreshed, f.mixed.ID)
314		if relisted.RevokedAt == nil || !relisted.RevokedAt.Equal(firstRevokedAt) {
315			t.Fatalf("relisted revoke time = %v, want %v", relisted.RevokedAt, firstRevokedAt)
316		}
317		if !reflect.DeepEqual(relisted, stored) {
318			t.Fatalf("relisted mixed grant diverges from stored:\n%+v\n%+v", relisted, stored)
319		}
320	
321		if got := totalAuthorizations(f.s); got != totalBefore {
322			t.Fatalf("authorization count changed: %d -> %d", totalBefore, got)
323		}
324		// 两次查询 + 本地篡改不新增审计；幂等重复撤回同样不新增事件。
325		if got := len(mustAudit(t, f.s, pid)); got != auditBefore {
326			t.Fatalf("audit event count changed: %d -> %d", auditBefore, got)
327		}
328	}
329	
330	// 同一条授权先后取得的两份清单、不指定接收方与按接收方筛选的清单互不影响：
331	// 篡改其中一份，较早拿到的另一份保留查询时的记录选择与撤回时间，
332	// 重新查询只反映正式保存的授权。
333	
334	func TestListAuthorizationsSnapshotsIndependentAcrossQueries(t *testing.T) {
335		// 混合授权先不撤回：早一批清单拿到的是“未撤回”的查询时刻状态。
336		f := setupListMutationFixture(t, false)
337		pid := f.particle
338	
339		beforeAll, err := f.s.ListAuthorizations(doc, pid, "")
340		if err != nil {
341			t.Fatalf("before list all: %v", err)
342		}
343		beforeRcv, err := f.s.ListAuthorizations(doc, pid, rcv.ID)
344		if err != nil {
345			t.Fatalf("before list receiver: %v", err)
346		}
347		if findListedAuth(t, beforeAll, f.mixed.ID).RevokedAt != nil {
348			t.Fatalf("pre-revoke snapshot already shows revocation")
349		}
350	
351		if err := f.s.Revoke(doc, pid, f.mixed.ID); err != nil {
352			t.Fatalf("revoke: %v", err)
353		}
354		nowRevoked, err := f.s.GetAuthorization(doc, pid, f.mixed.ID)
355		if err != nil {
356			t.Fatalf("get revoked: %v", err)
357		}
358	
359		afterAll, err := f.s.ListAuthorizations(doc, pid, "")
360		if err != nil {
361			t.Fatalf("after list all: %v", err)
362		}
363		afterRcv, err := f.s.ListAuthorizations(doc, pid, rcv.ID)
364		if err != nil {
365			t.Fatalf("after list receiver: %v", err)
366		}
367	
368		// 先篡改 afterAll：换掉限定授权的记录选择、清空混合授权的撤回时间。
369		tamperedAll := listedAuthPtr(t, afterAll, f.limited.ID)
370		tamperedAll.Selections[0].RecordID = f.dx3
371		listedAuthPtr(t, afterAll, f.mixed.ID).RevokedAt = nil
372	
373		// afterRcv 必须保持撤回后的正式样子，不受 afterAll 篡改影响。
374		rLimited := findListedAuth(t, afterRcv, f.limited.ID)
375		if len(rLimited.Selections) != 1 || rLimited.Selections[0] != sel(f.e, Diagnosis, f.dx1) {
376			t.Fatalf("afterRcv limited selection leaked from afterAll tamper: %+v", rLimited.Selections)
377		}
378		rMixed := findListedAuth(t, afterRcv, f.mixed.ID)
379		if rMixed.RevokedAt == nil || !rMixed.RevokedAt.Equal(*nowRevoked.RevokedAt) {
380			t.Fatalf("afterRcv revoke marker leaked from afterAll tamper: %v", rMixed.RevokedAt)
381		}
382	
383		// 再篡改 afterRcv：移除限定项、改掉混合授权限定项指向的记录。
384		listedAuthPtr(t, afterRcv, f.limited.ID).Selections = nil
385		listedAuthPtr(t, afterRcv, f.mixed.ID).Selections[0].RecordID = f.dx3
386	
387		// afterAll 只呈现它自己被改的样子，afterRcv 的篡改不回串：
388		// 它的混合授权撤回时间仍为本地清空的 nil，但限定项仍指向 dx2；
389		// limited 的记录仍是它自己替换的 dx3。
390		aMixed := findListedAuth(t, afterAll, f.mixed.ID)
391		if aMixed.RevokedAt != nil {
392			t.Fatalf("afterAll local revoke-clear lost: %v", aMixed.RevokedAt)
393		}
394		if len(aMixed.Selections) != 1 || aMixed.Selections[0] != sel(f.e, Diagnosis, f.dx2) {
395			t.Fatalf("afterAll mixed selection leaked from afterRcv tamper: %+v", aMixed.Selections)
396		}
397		if got := findListedAuth(t, afterAll, f.limited.ID).Selections[0].RecordID; got != f.dx3 {
398			t.Fatalf("afterAll local record swap lost: %v", got)
399		}
400	
401		// 较早拿到的两份清单保留各自查询时的状态：撤回时间仍为 nil，
402		// 限定项仍是 dx1/dx2，整类条目仍是 e/医嘱——后来的撤回与两份清单的
403		// 篡改都不回溯影响它们。
404		assertEarlySnapshot := func(t *testing.T, rows []Authorization, where string) {
405			t.Helper()
406			limited := findListedAuth(t, rows, f.limited.ID)
407			if len(limited.Selections) != 1 || limited.Selections[0] != sel(f.e, Diagnosis, f.dx1) {
408				t.Fatalf("%s: limited selection changed: %+v", where, limited.Selections)
409			}
410			mixed := findListedAuth(t, rows, f.mixed.ID)
411			if mixed.RevokedAt != nil {
412				t.Fatalf("%s: early snapshot acquired a revoke time: %v", where, mixed.RevokedAt)
413			}
414			if len(mixed.Selections) != 1 || mixed.Selections[0] != sel(f.e, Diagnosis, f.dx2) {
415				t.Fatalf("%s: mixed selection changed: %+v", where, mixed.Selections)
416			}
417			if len(mixed.Scopes) != 1 || mixed.Scopes[0] != (Scope{EncounterID: f.e, Category: Order}) {
418				t.Fatalf("%s: mixed scope changed: %+v", where, mixed.Scopes)
419			}
420		}
421		assertEarlySnapshot(t, beforeAll, "early unfiltered list")
422		assertEarlySnapshot(t, beforeRcv, "early receiver-filtered list")
423	
424		// 重新查询只反映正式保存的授权。
425		fresh, err := f.s.ListAuthorizations(doc, pid, "")
426		if err != nil {
427			t.Fatalf("fresh list: %v", err)
428		}
429		storedLimited, err := f.s.GetAuthorization(doc, pid, f.limited.ID)
430		if err != nil {
431			t.Fatalf("get limited: %v", err)
432		}
433		if got := findListedAuth(t, fresh, f.limited.ID); !reflect.DeepEqual(got, storedLimited) {
434			t.Fatalf("fresh limited row diverges from stored:\ngot  = %+v\nwant = %+v", got, storedLimited)
435		}
436		if got := findListedAuth(t, fresh, f.mixed.ID); !reflect.DeepEqual(got, nowRevoked) {
437			t.Fatalf("fresh mixed row diverges from stored:\ngot  = %+v\nwant = %+v", got, nowRevoked)
438		}
439	
440		// 读取行为以正式授权为准：仍只有 dx1；医嘱因唯一授权已撤回而被拒，
441		// 拒绝结果不带受保护内容。
442		res, err := f.s.Read(rcv, pid, f.e, Diagnosis)
443		if err != nil {
444			t.Fatalf("diagnosis read: %v", err)
445		}
446		if ids := readRecordIDs(res); len(res.Records) != 1 || !ids[f.dx1] || ids[f.dx2] || ids[f.dx3] {
447			t.Fatalf("diagnosis read = %v, want only dx1", ids)
448		}
449		denied, err := f.s.Read(rcv, pid, f.e, Order)
450		assertDeniedWithoutContent(t, denied, err, "orders covered only by revoked grant")
451	}
452

